window.RECS = {"status": "demo_content_to_be_validated_by_NDMA_WHH", "sources": {"ndma": "NDMA Kenya monthly drought early warning bulletins (ndma.go.ke)", "fao_aa": "FAO anticipatory action for drought, livestock protection packages (fao.org)", "cabot": "Cabot Venton 2012, Economics of early response and resilience, Kenya: early destocking returns about 390:1 per USD", "wfp": "WFP Kenya anticipatory cash and school feeding guidance", "hsnp": "NDMA Hunger Safety Net Programme (HSNP) scalable cash transfers"}, "items": [{"id": "herd_destock_early", "audience": "herder", "events": ["no_grass"], "phase": "prepare", "priority": 1, "drivers": ["veg", "rain"], "action": "Sell weak and old animals now while prices hold, keep breeding stock.", "action_sw": "Uza mifugo dhaifu na wazee sasa bei ikiwa nzuri, weka wazazi.", "detail": "Early destocking: sell old, weak and surplus animals before body condition falls and prices collapse; keep core breeding females. Commercial offtake through county livestock marketing associations.", "source": "cabot"}, {"id": "herd_move_dry_grazing", "audience": "herder", "events": ["no_grass"], "phase": "prepare", "priority": 2, "drivers": ["veg"], "action": "Plan to move herds to dry-season grazing early. Agree routes with elders.", "action_sw": "Panga kuhamisha mifugo mapema kwa malisho ya kiangazi. Kubaliana na wazee.", "detail": "Move herds to reserved dry-season grazing areas before pasture runs out; agree routes and water access with elders and neighbouring communities to avoid conflict.", "source": "ndma"}, {"id": "herd_water_vet", "audience": "herder", "events": ["no_grass"], "phase": "prepare", "priority": 3, "drivers": ["heat", "soil"], "action": "Vaccinate and deworm now. Keep animals near known water points.", "action_sw": "Chanja na toa dawa ya minyoo sasa. Weka mifugo karibu na maji.", "detail": "Vaccinate and deworm before the dry spell; weak animals die first from disease. Locate working boreholes and water pans.", "source": "fao_aa"}, {"id": "herd_sell_now", "audience": "herder", "events": ["no_grass"], "phase": "respond", "priority": 1, "drivers": ["veg"], "action": "No grass left: sell weak animals now, keep breeding females, move herds to water.", "action_sw": "Malisho yameisha: uza mifugo dhaifu, weka wazazi, peleka mifugo penye maji.", "detail": "Emergency destocking and offtake of animals unlikely to survive; protect breeding females; move to areas with water and residual pasture.", "source": "cabot"}, {"id": "herd_feed_supplement", "audience": "herder", "events": ["no_grass"], "phase": "respond", "priority": 2, "drivers": ["veg", "price"], "action": "Feed breeding females and young first. Ask the county for livestock feed.", "action_sw": "Lisha wazazi na wachanga kwanza. Omba chakula cha mifugo kwa kaunti.", "detail": "Supplementary feed (hay, pellets, mineral licks) targeted to breeding females and young stock; request county or NDMA livestock feed distribution.", "source": "fao_aa"}, {"id": "herd_crop_fail_sell", "audience": "herder", "events": ["crop_failure", "cant_plant", "any"], "phase": "both", "priority": 1, "drivers": ["rain"], "action": "Crops are failing: sell weak animals early, keep breeding stock, save water.", "action_sw": "Mazao yanaharibika: uza mifugo dhaifu mapema, weka wazazi, hifadhi maji.", "detail": "Where cropping fails, livestock become the main buffer; sell early and conserve water and residues for the herd.", "source": "ndma"}, {"id": "farm_keep_grain", "audience": "farmer", "events": ["crop_failure", "any"], "phase": "both", "priority": 1, "drivers": ["price"], "action": "Keep at least 2 months of grain for your family. Do not sell cheap.", "action_sw": "Weka nafaka ya miezi 2 kwa familia. Usiuze kwa bei ndogo.", "detail": "Hold household grain stock; prices normally rise after a poor harvest. Store in dry, pest-safe containers.", "source": "fao_aa"}, {"id": "farm_plant_wait", "audience": "farmer", "events": ["cant_plant"], "phase": "prepare", "priority": 1, "drivers": ["rain", "soil"], "action": "Wait for 2 good rains before planting. Use short-season seed.", "action_sw": "Subiri mvua nzuri 2 kabla ya kupanda. Tumia mbegu za muda mfupi.", "detail": "Avoid dry planting; choose short-season or drought-tolerant varieties (sorghum, millet, cowpea, green gram) and conservation agriculture.", "source": "ndma"}, {"id": "farm_tolerant_seed", "audience": "farmer", "events": ["crop_failure", "cant_plant", "any"], "phase": "prepare", "priority": 2, "drivers": ["rain", "soil"], "action": "Plan drought-tolerant seed for next season: sorghum, millet, green gram.", "action_sw": "Panga mbegu zinazovumilia ukame msimu ujao: mtama, ulezi, pojo.", "detail": "Order drought-tolerant seed early through extension services or agro-dealers; diversify to small grains and pulses.", "source": "fao_aa"}, {"id": "farm_relief_register", "audience": "farmer", "events": ["crop_failure", "cant_plant", "any"], "phase": "respond", "priority": 1, "drivers": ["rain"], "action": "Harvest failed: keep your grain, ask the chief or ward about relief.", "action_sw": "Mazao yameharibika: weka nafaka, uliza chifu kuhusu msaada.", "detail": "Register with the chief and county drought committee for relief food or cash; do not sell animals or grain cheaply.", "source": "ndma"}, {"id": "farm_no_grass_keep_stock", "audience": "farmer", "events": ["no_grass"], "phase": "both", "priority": 1, "drivers": ["veg"], "action": "Severe drought: keep grain for family, do not sell animals cheap.", "action_sw": "Ukame mkali: weka nafaka ya familia, usiuze mifugo kwa bei ndogo.", "detail": "Mixed households: protect food stock first, sell only weak animals, avoid distress sales.", "source": "ndma"}, {"id": "res_water_register", "audience": "resident", "events": ["any"], "phase": "both", "priority": 1, "drivers": ["rain"], "action": "Drought: food may get short. Keep clean water, register with your local food committee.", "detail": "Store clean drinking water, register with the ward or county relief committee, and report water point failures to the county.", "source": "ndma"}, {"id": "res_prices", "audience": "resident", "events": ["any"], "phase": "respond", "priority": 2, "drivers": ["price"], "action": "Food prices may rise. Buy staples early and report water or food problems to the chief.", "detail": "Expect staple price increases; buy early where possible and report hunger cases to the chief or the county.", "source": "wfp"}, {"id": "ngo_prepos_food", "audience": "ngo", "events": ["any"], "phase": "prepare", "priority": 1, "drivers": ["rain", "veg", "fews"], "action": "Pre-position food and cash plans for this county.", "detail": "Pre-position food stocks and agree cash transfer lists and partners now; align with the county drought contingency plan and NDMA phase classification.", "source": "wfp"}, {"id": "ngo_water_trucking", "audience": "ngo", "events": ["no_grass", "any"], "phase": "prepare", "priority": 2, "drivers": ["rain", "soil", "heat"], "action": "Check boreholes and plan water trucking.", "detail": "Inspect and repair boreholes and pans; map trucking routes and contractors before water points fail.", "source": "ndma"}, {"id": "ngo_destock_support", "audience": "ngo", "events": ["no_grass"], "phase": "prepare", "priority": 3, "drivers": ["veg"], "action": "Support commercial destocking and offtake.", "detail": "Fund or link early livestock offtake (traders, KMC, slaughter-and-distribute). Early destocking has returned about 390 USD of benefit per USD spent in Kenyan studies.", "source": "cabot"}, {"id": "ngo_cash_response", "audience": "ngo", "events": ["any"], "phase": "respond", "priority": 1, "drivers": ["price", "fews"], "action": "Start cash transfers and food distribution now.", "detail": "Trigger scalable cash transfers (HSNP) and general food assistance for affected wards; coordinate with the County Steering Group.", "source": "hsnp"}, {"id": "ngo_livestock_feed_vet", "audience": "ngo", "events": ["no_grass"], "phase": "respond", "priority": 2, "drivers": ["veg"], "action": "Deliver livestock feed and veterinary care.", "detail": "Distribute supplementary feed and run emergency vaccination and treatment campaigns; prioritise breeding females.", "source": "fao_aa"}, {"id": "ngo_school_feeding", "audience": "ngo", "events": ["any"], "phase": "respond", "priority": 3, "drivers": ["price"], "action": "Extend school feeding.", "detail": "Expand school meals programmes in affected wards to protect child nutrition and attendance.", "source": "wfp"}, {"id": "off_contingency_plan", "audience": "officer", "events": ["any"], "phase": "prepare", "priority": 1, "drivers": ["rain", "veg", "fews"], "action": "Activate the county drought contingency plan.", "detail": "Convene the County Steering Group, activate the drought contingency plan and request NDMA contingency funds; confirm the drought phase with the latest NDMA bulletin.", "source": "ndma"}, {"id": "off_extension", "audience": "officer", "events": ["crop_failure", "cant_plant"], "phase": "prepare", "priority": 2, "drivers": ["rain", "soil"], "action": "Push drought-tolerant seed and planting-date advice to worst-hit wards.", "detail": "Brief extension staff; distribute short-season and drought-tolerant seed; advise on planting dates.", "source": "fao_aa"}, {"id": "off_livestock_offtake", "audience": "officer", "events": ["no_grass"], "phase": "prepare", "priority": 2, "drivers": ["veg"], "action": "Organise livestock marketing and offtake days.", "detail": "Work with livestock marketing associations to hold offtake days and secure buyers before prices fall.", "source": "cabot"}, {"id": "off_water_infrastructure", "audience": "officer", "events": ["any"], "phase": "prepare", "priority": 3, "drivers": ["soil", "heat", "rain"], "action": "Repair boreholes and plan water trucking.", "detail": "Prioritise borehole and water pan repairs and prepare trucking schedules for the driest wards.", "source": "ndma"}, {"id": "off_declare_response", "audience": "officer", "events": ["any"], "phase": "respond", "priority": 1, "drivers": ["rain", "veg", "fews"], "action": "Declare the drought response and release relief.", "detail": "Escalate to the national and county governments; release relief food, water trucking and livestock feed; request partner support.", "source": "ndma"}, {"id": "off_cash_hsnp", "audience": "officer", "events": ["any"], "phase": "respond", "priority": 2, "drivers": ["price", "fews"], "action": "Scale up HSNP cash transfers and school feeding.", "detail": "Request NDMA to trigger HSNP scale-up for registered households and extend school feeding in affected wards.", "source": "hsnp"}, {"id": "fb_stock", "audience": "foodbank", "events": ["any"], "phase": "prepare", "priority": 1, "drivers": ["price", "fews"], "action": "Build stock for the county now.", "detail": "Buy and stage staples (maize, beans, oil) for the county ahead of price rises; agree distribution points with the chief and county.", "source": "wfp"}, {"id": "fb_distribute", "audience": "foodbank", "events": ["any"], "phase": "respond", "priority": 1, "drivers": ["price", "fews"], "action": "Distribute food to affected wards.", "detail": "Release stock to the worst-hit wards through the county relief committee; prioritise households with children and livestock losses.", "source": "wfp"}]};
